-- Đề kho bộ 's3_tuan' (F-S3-910001…006), phiên bản F-S3-910101…106
CREATE TEMP TABLE t_s3p (n int, code text, title text, statement text, answer text, hint1 text) ON COMMIT DROP;
SELECT format('00000000-0000-7000-8003-%s', lpad(t.n::text, 12, '0'))::uuid, platform_org_id(), 1, 'catalog',
       '00000000-0000-7000-8000-0000000000aa', 'thpt', NULL, 1, t.title, t.code, 's3_tuan', 'plane', :'t0'::timestamptz - interval '20 days'
FROM t_s3p t;
                             created_by, created_at)
SELECT format('00000000-0000-7000-8003-%s', lpad((t.n + 100)::text, 12, '0'))::uuid, platform_org_id(),
       format('00000000-0000-7000-8003-%s', lpad(t.n::text, 12, '0'))::uuid, 1, t.statement,
       digest(regexp_replace(btrim(t.statement), '\s+', ' ', 'g'), 'sha256'), 'teacher_approved', false,
       '00000000-0000-7000-8000-0000000000aa', :'t0'::timestamptz - interval '20 days'
FROM t_s3p t;
UPDATE problem pr SET current_version_id = format('00000000-0000-7000-8003-%s', lpad((t.n + 100)::text, 12, '0'))::uuid
FROM t_s3p t WHERE pr.org_id = platform_org_id() AND pr.id = format('00000000-0000-7000-8003-%s', lpad(t.n::text, 12, '0'))::uuid;
SELECT platform_org_id(), format('00000000-0000-7000-8003-%s', lpad((t.n + 100)::text, 12, '0'))::uuid, 1, t.hint1 FROM t_s3p t;
SELECT platform_org_id(), format('00000000-0000-7000-8003-%s', lpad((t.n + 100)::text, 12, '0'))::uuid, t.answer,
       jsonb_build_array(jsonb_build_object('title', 'Hướng làm', 'body', t.hint1, 'why', 'Đưa về đại lượng tính được.'),
                         jsonb_build_object('title', 'Kết quả', 'body', 'Đáp số: ' || t.answer || '.', 'why', 'Thay số.')),
       'gia-lap-1', 'p1', '00000000-0000-7000-8000-0000000000aa', false
FROM t_s3p t;

