INSERT INTO t_s3p VALUES
  (910001, 'TUAN-11', 'Đề 1 SC-đáy', 'Cho hình chóp S.ABCD có đáy là hình vuông cạnh 2, SA ⊥ (ABCD), SA = 2√2. Tính góc giữa SC và mặt đáy (độ).', '45', 'Hình chiếu của SC lên mặt đáy là AC.'),
  (910002, 'TUAN-12', 'Đề 2 d(A,SBC)', 'Cho hình chóp S.ABC có SA ⊥ (ABC), tam giác ABC vuông tại B, SA = 3, AB = 4. Tính khoảng cách từ A đến (SBC).', '12/5', 'Kẻ AH ⊥ SB; chứng minh AH ⊥ (SBC).'),
  (910003, 'TUAN-13', 'Đề 3 hai mặt phẳng', 'Cho hình chóp S.ABC có SA ⊥ (ABC), tam giác ABC vuông tại B, AB = 1, SA = √3. Tính góc giữa (SBC) và (ABC) (độ).', '60', 'Giao tuyến là BC; tìm hai đường cùng vuông góc với BC.'),
  (910004, 'TUAN-14', 'Đề 4 thể tích', 'Cho hình chóp S.ABCD có đáy là hình vuông cạnh 3, SA ⊥ (ABCD), SA = 4. Tính thể tích khối chóp.', '12', 'V = ⅓ · diện tích đáy · chiều cao.'),
  (910005, 'TUAN-21', 'Đề 5 lăng trụ', 'Lăng trụ đứng ABC.A′B′C′ có đáy là tam giác vuông tại A, AB = 3, AC = 4, AA′ = 4. Tính thể tích khối lăng trụ.', '24', 'V = diện tích đáy · chiều cao.'),
  (910006, 'TUAN-22', 'Đề 6 khoảng cách', 'Cho hình lập phương ABCD.A′B′C′D′ cạnh 5. Tính khoảng cách giữa hai mặt phẳng (ABCD) và (A′B′C′D′).', '5', 'Hai mặt đáy song song, khoảng cách bằng cạnh bên.');
